ee:message.ee:set-payload:
%dw 2.0
import * from dw::Crypto
import toHex from dw::core::Binaries
output application/json

// ── Raw input ────────────────────────────────────────────────────────────────
var p   = payload default {}
var old = vars.existingProduct default null

// ── Normalised scalar fields ──────────────────────────────────────────────────
var sku           = trim((p.sku           default "") as String)
var productName   = trim((p.productName   default "") as String)
var categoryCode  = trim((p.categoryCode  default "") as String)
var brand         = trim((p.brand         default "") as String)
var currency      = upper(trim((p.currency  default "") as String))
var taxClass      = trim((p.taxClass      default "") as String)
var stockStatus   = upper(trim((p.stockStatus  default "") as String))
var productStatus = upper(trim((p.productStatus default "") as String))
var imagePath     = trim((p.imagePath     default "") as String)

// Supported value lists
var supportedCurrencies   = ["INR", "USD", "EUR", "GBP", "AED", "SGD", "AUD"]
var supportedStockStatus  = ["IN_STOCK", "OUT_OF_STOCK", "DISCONTINUED"]
var supportedProductStatus= ["ACTIVE", "INACTIVE", "DELISTED"]

// Price – kept as Number to avoid repeated casts downstream
var priceRaw    = p.price default null
var priceNumber = if (priceRaw == null) null
                  else do {
                      var s = trim(priceRaw as String)
                      ---
                      if (s matches /^[0-9]+([.][0-9]+)?$/) (s as Number)
                      else null
                  }

// ── Validation ────────────────────────────────────────────────────────────────
var errors =
    (if (isEmpty(sku))
        ["SKU is required and must not be empty"]
    else []) ++
    (if (isEmpty(productName))
        ["Product name is required"]
    else []) ++
    (if (isEmpty(categoryCode))
        ["Category code is required"]
    else []) ++
    (if (isEmpty(brand))
        ["Brand is required"]
    else []) ++
    (if (priceRaw == null)
        ["Price is required"]
    else if (priceNumber == null)
        ["Price must be a positive number"]
    else if (priceNumber <= 0)
        ["Price must be greater than zero"]
    else []) ++
    (if (isEmpty(currency))
        ["Currency is required"]
    else if (!(supportedCurrencies contains currency))
        ["Currency '" ++ currency ++ "' is not supported; supported values: " ++ (supportedCurrencies joinBy ", ")]
    else []) ++
    (if (isEmpty(taxClass))
        ["Tax class is required"]
    else []) ++
    (if (isEmpty(stockStatus))
        ["Stock status is required"]
    else if (!(supportedStockStatus contains stockStatus))
        ["Invalid stock status '" ++ stockStatus ++ "'; supported: " ++ (supportedStockStatus joinBy ", ")]
    else []) ++
    (if (isEmpty(productStatus))
        ["Product status is required"]
    else if (!(supportedProductStatus contains productStatus))
        ["Invalid product status '" ++ productStatus ++ "'; supported: " ++ (supportedProductStatus joinBy ", ")]
    else []) ++
    (if (isEmpty(imagePath) or not (imagePath startsWith "/img/"))
        ["Image path must start with /img/"]
    else [])

// ── Canonical comparable snapshot (hash input) ────────────────────────────────
// Only fields that represent the product's content are hashed.
// importRunId, sourceTimestamp, and other pipeline-metadata fields are excluded.
var comparable = {
    sku          : sku,
    productName  : productName,
    categoryCode : categoryCode,
    brand        : brand,
    price        : if (priceNumber != null) priceNumber else priceRaw,
    currency     : currency,
    taxClass     : taxClass,
    stockStatus  : stockStatus,
    productStatus: productStatus,
    shortDescription: trim((p.shortDescription default "") as String),
    imagePath    : imagePath
}

// ── Content hash ──────────────────────────────────────────────────────────────
// dw::Crypto::hashWith(content: Binary, algorithm: String): Binary
// dw::core::Binaries::toHex(content: Binary): String
var hashInput   = write(comparable, "application/json", {indent: false})
var contentHash = toHex(hashWith((hashInput as Binary), "SHA-256"))

// ── Field-level change detection ──────────────────────────────────────────────
// All fields tracked for change (including internal-only taxClass)
var trackedFields = [
    "productName", "categoryCode", "brand", "price",
    "currency", "taxClass", "stockStatus", "productStatus",
    "shortDescription", "imagePath"
]

// Customer-facing subset: changes here warrant CDN invalidation
var customerFacingFields = [
    "productName", "categoryCode", "brand", "price",
    "currency", "stockStatus", "productStatus",
    "shortDescription", "imagePath"
]

var changedFields =
    if (old == null) []
    else trackedFields filter ((field) ->
        (comparable[field] default null) != ((old[field] default null) as String {class: "java.lang.Object"} default null)
    )

var customerFacingChange =
    if (old == null) true   // new product is always customer-facing
    else changedFields some ((f) -> customerFacingFields contains f)

// ── Price-change review threshold (30 %) ──────────────────────────────────────
var existingPrice = if (old == null) null
                    else do {
                        var raw = old.price default null
                        ---
                        if (raw == null) null
                        else (raw as Number)
                    }

var priceReviewRequired =
    (old != null)
    and (existingPrice != null)
    and (existingPrice != 0)
    and (priceNumber   != null)
    and (existingPrice != priceNumber)
    and (
        abs((priceNumber - existingPrice) / existingPrice) > 0.30
    )

// ── Classification ────────────────────────────────────────────────────────────
var classification =
    if (sizeOf(errors) > 0)                         "REJECTED"
    else if ((vars.reviewHold default false)
             or priceReviewRequired)                 "HOLD"
    else if (old == null)                            "NEW"
    else if (sizeOf(changedFields) == 0)             "UNCHANGED"
    else                                             "CHANGED"

---
{
    sku                : sku,
    classification     : classification,
    contentHash        : contentHash,
    changedFields      : changedFields,
    customerFacingChange : customerFacingChange,
    priceReviewRequired  : priceReviewRequired,
    validationErrors   : errors,
    product            : p
}
